1181	// Same as dectc_gemm_fwd but emits the fp32 result (no bf16 round) — for the
1182	// few fwd outputs consumed by fp32 elementwise stages directly. Writes [M,Nout]
1183	// fp32 at `Yf32`.
1184	template <int N>
1185	__device__ __forceinline__ void dectc_gemm_fwd_f32(
1186	        const __nv_bfloat16* __restrict__ X, const __nv_bfloat16* __restrict__ W,
1187	        float* __restrict__ Yf32, int Kin, int Nout,
1188	        __nv_bfloat16* sA, __nv_bfloat16* sB, unsigned long long* pipeBars = nullptr) {
1189	    const int k_steps = Kin / wgs::kWgmmaAtomK;
1190	    for (int n0 = 0; n0 < Nout; n0 += N) {
1191	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
1192	        // Same flat-gmem K-major sources as dectc_gemm_fwd (C1 cache B operand;
1193	        // RING-staged); only the fp32 output accessor differs.
1194	        DecGmemTileSrcA srcA{X, Kin};
1195	        DecGmemTileSrcB srcB{W + (int64_t)n0 * Kin, Kin, Nout - n0};
1196	        auto out  = [&] (int m, int n, float v) { Yf32[(int64_t)m * Nout + n0 + n] = v; };
1197	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
1198	            0, kAtomsM, n_real, k_steps, srcA, srcB, out, sA, sB, pipeBars SG_DEC_FINE_FWD);
1199	    }
1200	}
