1202	// (dX) dX[M,Kin] = dY[M,Nout] @ W[Nout,Kin].  N(wgmma) = Kin (the in_dim, tiled
1203	// by width N). K = Nout (the contracted out_dim). The B operand is staged from
1204	// the TRANSPOSED cache section (C1-T, dec_wbf_bind's *_wT): srcB(n=kin, k=out)
1205	// = WT[kin·Nout + out] == W[out·Kin + kin] BIT-IDENTICALLY (the transposed copy
1206	// holds the same deterministically-rounded bf16 values) — but K-CONTIGUOUS, so
1207	// the cp.async ring streams the dX weight operand too (the old row-major W read
1208	// was k-strided: a 2-byte gather no 4/8/16B async copy can express). Writes
1209	// fp32 dX [M,Kin] (LN/elementwise bwd consume it fp32).
1210	template <int N>
1211	__device__ __forceinline__ void dectc_gemm_dx_f32(
1212	        const __nv_bfloat16* __restrict__ dY, const __nv_bfloat16* __restrict__ WT,
1213	        float* __restrict__ dXf32, int Kin, int Nout,
1214	        __nv_bfloat16* sA, __nv_bfloat16* sB, unsigned long long* pipeBars = nullptr) {
1215	    const int k_steps = Nout / wgs::kWgmmaAtomK;
1216	    for (int n0 = 0; n0 < Kin; n0 += N) {
1217	        const int n_real = (Kin - n0) < N ? (Kin - n0) : N;
1218	        DecGmemTileSrcA srcA{dY, Nout};
1219	        DecGmemTileSrcB srcB{WT + (int64_t)n0 * Nout, Nout, Kin - n0};
1220	        auto out  = [&] (int m, int n, float v) { dXf32[(int64_t)m * Kin + n0 + n] = v; };
1221	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
1222	            0, kAtomsM, n_real, k_steps, srcA, srcB, out, sA, sB, pipeBars SG_DEC_FINE_DX);
1223	    }
1224	}
