1226	// ── fp32-W OVERLOADS (TP-path compatibility; pre-C1 convert-on-read bodies).
1227	//    The C1 weight pre-stage scoped the megakernel's GEMM B operand to the bf16
1228	//    cache, but the TENSOR-PARALLEL layer (csrc/fused/sm_90/tp_layer.cuh and its
1229	//    JIT test binding tests/hw/tp_loopback_binding.cu) stages PER-RANK fp32
1230	//    weight SHARDS that live outside the megakernel workspace — no C1 cache
1231	//    exists there. These overloads carry the EXACT pre-C1 accessor bodies
1232	//    (`__float2bfloat16(W[...])` on read — deterministic, bit-identical to what
1233	//    the TP path always consumed), selected by the fp32 pointer type. The
1234	//    megakernel never calls them (its W is the bf16 cache). ──
1235	template <int N>
1236	__device__ __forceinline__ void dectc_gemm_fwd_f32(
1237	        const __nv_bfloat16* __restrict__ X, const float* __restrict__ W,

1237	        const __nv_bfloat16* __restrict__ X, const float* __restrict__ W,
1238	        float* __restrict__ Yf32, int Kin, int Nout,
1239	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1240	    const int k_steps = Kin / wgs::kWgmmaAtomK;
1241	    for (int n0 = 0; n0 < Nout; n0 += N) {
1242	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
1243	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
1244	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1245	            int nn = n0 + n; return nn < Nout ? __float2bfloat16(W[(int64_t)nn * Kin + k]) : __float2bfloat16(0.f); };
1246	        auto out  = [&] (int m, int n, float v) { Yf32[(int64_t)m * Nout + n0 + n] = v; };
1247	        // fp32-W (TP) lambda sources → !kRingAsync (no stamp; never reaches the
1248	        // PIPE=2 engine) → pipeBars=nullptr; tag kept for intent.
1249	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
1250	            0, kAtomsM, n_real, k_steps, srcA, srcB, out, sA, sB, /*pipeBars=*/nullptr SG_DEC_FINE_FWD);
1251	    }
1252	}
1253	template <int N>
1254	__device__ __forceinline__ void dectc_gemm_dx_f32(
1255	        const __nv_bfloat16* __restrict__ dY, const float* __restrict__ W,
1256	        float* __restrict__ dXf32, int Kin, int Nout,
1257	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1258	    const int k_steps = Nout / wgs::kWgmmaAtomK;
1259	    for (int n0 = 0; n0 < Kin; n0 += N) {
1260	        const int n_real = (Kin - n0) < N ? (Kin - n0) : N;
1261	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
1262	        // B[n=kin, k=out] = W[out, kin]  (transposed read; fp32 → bf16).
1263	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1264	            int nn = n0 + n; return nn < Kin ? __float2bfloat16(W[(int64_t)k * Kin + nn]) : __float2bfloat16(0.f); };
1265	        auto out  = [&] (int m, int n, float v) { dXf32[(int64_t)m * Kin + n0 + n] = v; };
1266	        // fp32-W (TP) lambda sources → !kRingAsync (no stamp; never reaches the
1267	        // PIPE=2 engine) → pipeBars=nullptr; tag kept for intent.
1268	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
1269	            0, kAtomsM, n_real, k_steps, srcA, srcB, out, sA, sB, /*pipeBars=*/nullptr SG_DEC_FINE_DX);
1270	    }
1271	}
