1273	// ════════════════════════════════════════════════════════════════════════
1274	//  Per-CTA TILE SCRATCH (HBM). One tile's forward intermediates the backward
1275	//  reads, reused across the tiles a CTA grid-strides over (a CTA finishes a
1276	//  tile's fwd+bwd before the next tile, so one slab per CTA suffices). Sized
1277	//  for kTileM rows. The X-inputs / dY-adjoints that OTHER CTAs read in P2's dW
1278	//  do NOT live here — they live in the full-T DecActs (cross-CTA). This holds
1279	//  only the within-tile fwd state + the running adjoint so the backward needs
1280	//  NO recompute.
1281	//
1282	//  DEDICATED, NON-ALIASED buffers (the TC test sizes its own workspace; HBM is
1283	//  NOT scarce, so hand-managed aliasing — the stride/alias bug class that bit
1284	//  the scalar path at model_stages_decoder.cuh:619-625, which the CPU mirror
1285	//  does NOT cover for tile-batched reuse — is avoided entirely). Each fp32
1286	//  intermediate gets its own slot.
1287	// ════════════════════════════════════════════════════════════════════════
1288	
1289	// nSamp samples per tile, H*S*S attention entries each; V logits each.
1290	constexpr int kNSampPerTile  = kTileM / dec::kSeq;
1291	constexpr int kAttnPerTile   = kNSampPerTile * dec::kHeads * dec::kSeq * dec::kSeq;
1292	constexpr int kLogitsPerTile = kNSampPerTile * dec::kVocab;
1293	
1294	// CRITICAL: the forward runs ALL layers, THEN the backward runs ALL layers (NOT
1295	// interleaved per-layer). So every forward intermediate the backward reads PER
1296	// LAYER must be stored PER LAYER — a single-buffered cache holds only the LAST
1297	// layer's values and the earlier layers' backward reads garbage (the "forward
1298	// exact, layer-0 grads wrong, error compounds backward" bug). qkv / ff0pre /
1299	// attn / n1·n2 LN caches are therefore [kLayers]-indexed. fnx/fni (final norm,
1300	// one instance) + the transient dh/x1/finalin/logits/work/work2/dsc stay single.
1301	struct DecTileScratch {
1302	    __nv_bfloat16* qkv[dec::kLayers];     // [kTileM, 3d]  per layer
1303	    __nv_bfloat16* ff0pre[dec::kLayers];  // [kTileM, dff] per layer
1304	    float* attn[dec::kLayers];            // [kAttnPerTile] per layer
1305	    float* n1x[dec::kLayers]; float* n1i[dec::kLayers];
1306	    float* n2x[dec::kLayers]; float* n2i[dec::kLayers];
1307	    float* dsc;             // [kAttnPerTile] attention dscores (transient, bwd-only)
1308	    float* fnx; float* fni; // final-norm LN caches (single)
1309	    float* dh;              // [kTileM, d]    running adjoint wrt block output
1310	    float* x1;              // [kTileM, d]    n1 output (fp32, residual base for r2)
1311	    float* finalin;         // [kTileM, d]    last-layer n2 output (fp32, head input)
1312	    float* logits;          // [kLogitsPerTile] per-sample last-pos logits (fp32)
1313	    float* work;            // [kTileM, dff]  GEMM output / general fp32 scratch
1314	    float* work2;           // [kTileM, dff]  second fp32 scratch (bwd dx1/dqkv)
1315	};
1316	
1317	// Bytes one CTA's scratch occupies (for host sizing of the workspace tail).
1318	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_bf16_count() {
1319	    // (qkv + ff0pre) per layer.
1320	    return (int64_t)dec::kLayers * ((int64_t)kTileM * 3 * dec::kD + (int64_t)kTileM * dec::kDff);
1321	}
1322	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_f32_count() {
1323	    return (int64_t)dec::kLayers * (                     // per-layer:
1324	             (int64_t)kAttnPerTile                       //   attn
1325	           + 2 * ((int64_t)kTileM * dec::kD + kTileM))    //   n1+n2 xhat+inv
1326	         + (int64_t)kAttnPerTile                          // dsc (single)
1327	         + ((int64_t)kTileM * dec::kD + kTileM)           // fn xhat+inv (single)
1328	         + (int64_t)kTileM * dec::kD                      // dh
1329	         + (int64_t)kTileM * dec::kD                      // x1
1330	         + (int64_t)kTileM * dec::kD                      // finalin
1331	         + (int64_t)kLogitsPerTile                        // logits
1332	         + 2 * (int64_t)kTileM * dec::kDff;               // work + work2
1333	}
1334	__host__ __device__ __forceinline__ int64_t dec_tile_scratch_total_f32() {
1335	    return (dec_tile_scratch_bf16_count() + 1) / 2 + dec_tile_scratch_f32_count();
1336	}
1337	
1338	__device__ __forceinline__ DecTileScratch dec_tile_scratch_bind(float* slab) {
1339	    DecTileScratch s;
1340	    __nv_bfloat16* b = reinterpret_cast<__nv_bfloat16*>(slab);
1341	    int64_t bo = 0;
1342	    for (int li = 0; li < dec::kLayers; ++li) { s.qkv[li]    = b + bo; bo += (int64_t)kTileM * 3 * dec::kD; }
1343	    for (int li = 0; li < dec::kLayers; ++li) { s.ff0pre[li] = b + bo; bo += (int64_t)kTileM * dec::kDff; }
1344	    float* f = slab + (dec_tile_scratch_bf16_count() + 1) / 2;
1345	    int64_t fo = 0;
1346	    for (int li = 0; li < dec::kLayers; ++li) { s.attn[li] = f + fo; fo += kAttnPerTile; }
1347	    for (int li = 0; li < dec::kLayers; ++li) { s.n1x[li] = f + fo; fo += (int64_t)kTileM * dec::kD; s.n1i[li] = f + fo; fo += kTileM; }
1348	    for (int li = 0; li < dec::kLayers; ++li) { s.n2x[li] = f + fo; fo += (int64_t)kTileM * dec::kD; s.n2i[li] = f + fo; fo += kTileM; }
1349	    s.dsc  = f + fo; fo += kAttnPerTile;
1350	    s.fnx  = f + fo; fo += (int64_t)kTileM * dec::kD;
1351	    s.fni  = f + fo; fo += kTileM;
1352	    s.dh   = f + fo; fo += (int64_t)kTileM * dec::kD;
1353	    s.x1   = f + fo; fo += (int64_t)kTileM * dec::kD;
1354	    s.finalin = f + fo; fo += (int64_t)kTileM * dec::kD;
1355	    s.logits  = f + fo; fo += kLogitsPerTile;
1356	    s.work    = f + fo; fo += (int64_t)kTileM * dec::kDff;
1357	    s.work2   = f + fo; fo += (int64_t)kTileM * dec::kDff;
1358	    return s;
1359	}
