1361	// ════════════════════════════════════════════════════════════════════════
1362	//  TILE-AWARE SCALAR ELEMENTWISE STAGES (fp32, CTA-cooperative over kTileM
1363	//  rows). These mirror the scalar oracle's per-row math (model_stages_decoder
1364	//  .cuh) but operate on a whole tile of `nrows` rows at once, reading/writing
1365	//  HBM [rows×width] buffers. Reductions reuse the validated dec_block_sum /
1366	//  dec_block_max helpers (whole-block, looped per row — LN/softmax are ≪1% of
1367	//  FLOPs, so the sequential row loop is not a bottleneck). `red` is a 256-float
1368	//  smem reduction slot (from the engine's smem arena).
1369	// ════════════════════════════════════════════════════════════════════════
1370	
1371	// LayerNorm fwd over the last dim d, for `nrows` rows. y, xhat are fp32 HBM
1372	// [rows×d]; inv is fp32 HBM [rows]. gamma/beta are fp32 [d] (params). Caches
1373	// xhat+inv for the bwd (identical to dec_layernorm_fwd but tiled).
1374	__device__ __forceinline__ void dectc_ln_fwd_tile(
1375	        const float* __restrict__ x, const float* __restrict__ gamma,
1376	        const float* __restrict__ beta, int nrows,
1377	        float* __restrict__ y, float* __restrict__ xhat, float* __restrict__ inv,
1378	        float* red) {
1379	    for (int s = 0; s < nrows; ++s) {
1380	        const float* xr = x + (int64_t)s * dec::kD;
1381	        float sum = 0.0f;
1382	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += xr[j];
1383	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
1384	        float vs = 0.0f;
1385	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = xr[j] - mean; vs += c * c; }
1386	        float var = dec_block_sum(vs, red) / (float)dec::kD;
1387	        float iv = rsqrtf(var + dec::kLnEps);
1388	        if (threadIdx.x == 0) inv[s] = iv;
1389	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1390	            float xh = (xr[j] - mean) * iv;
1391	            xhat[(int64_t)s * dec::kD + j] = xh;
1392	            y[(int64_t)s * dec::kD + j] = xh * gamma[j] + beta[j];
1393	        }
1394	        __syncthreads();
1395	    }
1396	}
