1398	// LayerNorm bwd for `nrows` rows: dy [rows×d] fp32, cached xhat/inv → dx [rows×d]
1399	// fp32; ACCUMULATES dgamma/dbeta (summed over the tile's rows) into a per-CTA
1400	// LN-vec partial slot gw/gb [d] (plain += : single owner thread per feature j
1401	// across rows, deterministic — same rule as the scalar dec_layernorm_bwd).
1402	__device__ __forceinline__ void dectc_ln_bwd_tile(
1403	        const float* __restrict__ dy, const float* __restrict__ xhat,
1404	        const float* __restrict__ inv, const float* __restrict__ gamma, int nrows,
1405	        float* __restrict__ dx, float* __restrict__ gw, float* __restrict__ gb,
1406	        float* red) {
1407	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1408	        float dgw = 0.0f, dgb = 0.0f;
1409	        for (int s = 0; s < nrows; ++s) {
1410	            float d = dy[(int64_t)s * dec::kD + j];
1411	            dgb += d; dgw += d * xhat[(int64_t)s * dec::kD + j];
1412	        }
1413	        gw[j] += dgw; gb[j] += dgb;
1414	    }
1415	    for (int s = 0; s < nrows; ++s) {
1416	        const float* dyr = dy + (int64_t)s * dec::kD;
1417	        const float* xhr = xhat + (int64_t)s * dec::kD;
1418	        float sda = 0.0f, sdax = 0.0f;
1419	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1420	            float dxhat = dyr[j] * gamma[j]; sda += dxhat; sdax += dxhat * xhr[j];
1421	        }
1422	        sda = dec_block_sum(sda, red);
1423	        sdax = dec_block_sum(sdax, red);
1424	        float iv = inv[s];
1425	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1426	            float dxhat = dyr[j] * gamma[j];
1427	            dx[(int64_t)s * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1428	        }
1429	        __syncthreads();
1430	    }
1431	}
