1433	// Per-sample causal self-attention FORWARD over a tile. qkv is bf16 HBM
1434	// [rows×3d] (q|k|v). Writes ctx fp32 HBM [rows×d] and attn weights fp32 to
1435	// `attn_w` [nSamp×H×S×S]. Each (sample,head,qpos) row is owned by one thread —
1436	// identical math to dec_forward_sample's attention block, looped over samples.
1437	__device__ __forceinline__ void dectc_attn_fwd_tile(
1438	        const __nv_bfloat16* __restrict__ qkv, int nrows,
1439	        float* __restrict__ ctx, float* __restrict__ attn_w) {
1440	    const int nsamp = nrows / dec::kSeq;
1441	    const float scale = dec::attn_scale();
1442	    const int rows_per = nsamp * dec::kHeads * dec::kSeq;   // (sample,head,qpos)
1443	    for (int r = threadIdx.x; r < rows_per; r += blockDim.x) {
1444	        const int si = r / (dec::kHeads * dec::kSeq);
1445	        const int rem = r % (dec::kHeads * dec::kSeq);
1446	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
1447	        const int qoff = hh * dec::kDhead;
1448	        const int rbase = si * dec::kSeq;        // first row of this sample
1449	        const __nv_bfloat16* qrow = qkv + (int64_t)(rbase + qi) * 3 * dec::kD + qoff;
1450	        float maxs = -CUDART_INF_F; float sc[dec::kSeq];
1451	        #pragma unroll
1452	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1453	            if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
1454	            const __nv_bfloat16* krow = qkv + (int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff;
1455	            float dot = 0.0f;
1456	            #pragma unroll
1457	            for (int t = 0; t < dec::kDhead; ++t)
1458	                dot += __bfloat162float(qrow[t]) * __bfloat162float(krow[t]);
1459	            sc[kj] = dot * scale; maxs = fmaxf(maxs, sc[kj]);
1460	        }
1461	        float denom = 0.0f;
1462	        #pragma unroll
1463	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1464	            float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f; sc[kj] = e; denom += e;
1465	        }
1466	        float invd = 1.0f / denom;
1467	        float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
1468	        #pragma unroll
1469	        for (int kj = 0; kj < dec::kSeq; ++kj) aw[kj] = sc[kj] * invd;
1470	        #pragma unroll
1471	        for (int t = 0; t < dec::kDhead; ++t) {
1472	            float acc = 0.0f;
1473	            #pragma unroll
1474	            for (int kj = 0; kj <= qi; ++kj) {
1475	                float vv = __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
1476	                acc += aw[kj] * vv;
1477	            }
1478	            ctx[(int64_t)(rbase + qi) * dec::kD + qoff + t] = acc;
1479	        }
1480	    }
1481	    __syncthreads();
1482	}
