1484	// Global SAMPLE index of the si-th sample in a tile whose first token row is g0.
1485	__device__ __forceinline__ int si_global(int g0, int si) { return g0 / dec::kSeq + si; }
1486	
1487	// ════════════════════════════════════════════════════════════════════════
1488	//  FORWARD over one TOKEN TILE (nrows = nsamp samples × kSeq positions), global
1489	//  token rows [g0, g0+nrows). Tile-batched: the four per-layer linears
1490	//  (in_proj/out_proj/ff0/ff2) run on wgmma (M=nrows, N-tiled); attention/LN/
1491	//  GELU are scalar fp32 over the tile; head/CE are scalar per-sample (M=nsamp<
1492	//  64). Writes the DecActs X-inputs (bf16 dW operands), the per-CTA tile scratch
1493	//  (qkv/ff0pre/attn/LN caches/x1/finalin/logits the bwd needs), and returns the
1494	//  tile's summed NLL (thread 0 holds it). `tok_ids`/`tgt_ids` are HBM int32.
1495	//
1496	//  DATAFLOW (DecActs X-regions = bf16 dW operands AND inter-stage operands;
1497	//  dedicated fp32 scratch for residuals/LN; weights convert fp32→bf16 on read):
1498	//    X_in[li]  := layer input (bf16)           [embedding for li=0]
1499	//    qkv(bf16) := X_in @ in_w^T + in_b   (in_b folded fp32 → re-round bf16)
1500	//    ctx       := attn(qkv) → X_ctx[li] (bf16, out_proj input + dW operand)
1501	//    a(work)   := X_ctx @ out_w^T ; r1=X_in+a+out_b (work); n1(r1)→x1(fp32)→X_x1[li]
1502	//    ff0(work) := X_x1 @ ff0_w^T ; (ff0+ff0_b)→ff0pre(bf16); gelu(ff0+ff0_b)→X_gact[li](bf16)
1503	//    ff2(work) := X_gact @ ff2_w^T ; r2=x1+ff2+ff2_b (work); n2(r2)→X_in[li+1]
1504	//                 (last layer: n2→finalin fp32, the head input)
1505	//  BIASES (in/out/ff0/ff2) are folded in fp32 at these points (the oracle adds
1506	//  them in fp32 after the bf16 matmul); LN β + head out_b were already applied.
1507	// ════════════════════════════════════════════════════════════════════════
1508	__device__ float dectc_forward_tile(
1509	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
1510	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
1511	        const int* __restrict__ tgt_ids,
1512	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1513	        unsigned long long* pipeBars = nullptr) {
1514	    const int nsamp = nrows / dec::kSeq;
1515	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
1516	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1517	        const int r = idx / dec::kD, j = idx % dec::kD;
1518	        const int g = g0 + r;
1519	        const int tid = tok_ids[g];
1520	        const int sp = g % dec::kSeq;            // position within the sample
1521	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
1522	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
1523	    }
1524	    __syncthreads();
1525	
1526	    for (int li = 0; li < dec::kLayers; ++li) {
1527	        const DecWeights::Layer& L = w.layer[li];
1528	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
1529	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
1530	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB, pipeBars);
1531	        __syncthreads();
1532	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
1533	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
1534	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
1535	            const int j = idx % (3 * dec::kD);
1536	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
1537	            sc.qkv[li][idx] = __float2bfloat16(v);
1538	        }
1539	        __syncthreads();
1540	        // attention → ctx (work fp32) + attn[li] weights.
1541	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
1542	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
1543	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1544	            const int r = idx / dec::kD, j = idx % dec::kD;
1545	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
1546	        }
1547	        __syncthreads();
1548	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.
1549	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
1550	                                            sc.work, dec::kD, dec::kD, sA, sB, pipeBars);
1551	        __syncthreads();
1552	        // r1 = Xin + a + out_b → work (fp32). out_b folded here (the GEMM did W only)
1553	        // — matches the oracle a = ctx_b @ out_w^T + out_b kept fp32 through r1.
1554	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1555	            const int r = idx / dec::kD, j = idx % dec::kD;
1556	            sc.work[(int64_t)r * dec::kD + j] += __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + L.out_b[j];
1557	        }
1558	        __syncthreads();
1559	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li] (ff0 input + dW operand).
1560	        dectc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
1561	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1562	            const int r = idx / dec::kD, j = idx % dec::kD;
1563	            acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * dec::kD + j]);
1564	        }
1565	        __syncthreads();
1566	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b)  (N=dff, K=d). fp32 → work; (pre+b) bf16 →
1567	        // ff0pre; gelu(pre+b) → X_gact[li] (bf16, ff2 input + dW operand). ff0_b folded
1568	        // into pre (fp32) — matches the oracle ff0pre=bf(ff0+b), gact=bf(gelu(ff0+b)).
1569	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * dec::kD, wb.ff0_w[li],
1570	                                            sc.work, dec::kD, dec::kDff, sA, sB, pipeBars);
1571	        __syncthreads();
1572	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1573	            const int r = idx / dec::kDff, j = idx % dec::kDff;
1574	            float pre = sc.work[(int64_t)r * dec::kDff + j] + L.ff0_b[j];
1575	            sc.ff0pre[li][(int64_t)r * dec::kDff + j] = __float2bfloat16(pre);
1576	            acts.X_gact[li][(int64_t)(g0 + r) * dec::kDff + j] = __float2bfloat16(dec_gelu(pre));
1577	        }
1578	        __syncthreads();
1579	        // ff2 = X_gact @ ff2_w^T (+ ff2_b) (N=d, K=dff). fp32 → work.
1580	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * dec::kDff, wb.ff2_w[li],
1581	                                            sc.work, dec::kDff, dec::kD, sA, sB, pipeBars);
1582	        __syncthreads();
1583	        // r2 = x1 + ff2 + ff2_b → work (fp32). x1 lives in the dedicated fp32 buffer
1584	        // (no bf16 round). ff2_b folded here — matches the oracle r2 = x1 + (ff2 + ff2_b).
1585	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1586	            const int r = idx / dec::kD, j = idx % dec::kD;
1587	            sc.work[(int64_t)r * dec::kD + j] += sc.x1[(int64_t)r * dec::kD + j] + L.ff2_b[j];
1588	        }
1589	        __syncthreads();
1590	        if (li + 1 < dec::kLayers) {
1591	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
1592	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
1593	            for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1594	                const int r = idx / dec::kD, j = idx % dec::kD;
1595	                acts.X_in[li + 1][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * dec::kD + j]);
1596	            }
1597	            __syncthreads();
1598	        } else {
1599	            // last layer: n2(r2) → finalin (fp32, all positions; head reads last pos) + n2 caches[li].
1600	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
1601	        }
1602	    }
1603	
1604	    // ── Final norm + head + CE, scalar PER-SAMPLE on the LAST position only.
1605	    //    finalin holds the last-layer n2 output [nrows,d] fp32. ──
1606	    float nll_acc = 0.0f;
1607	    for (int si = 0; si < nsamp; ++si) {
1608	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
1609	        const float* hlast = sc.finalin + (int64_t)rlast * dec::kD;
1610	        float sum = 0.0f;
1611	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
1612	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
1613	        float vs = 0.0f;
1614	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
1615	        float var = dec_block_sum(vs, red) / (float)dec::kD;
1616	        float iv = rsqrtf(var + dec::kLnEps);
1617	        if (threadIdx.x == 0) sc.fni[rlast] = iv;
1618	        // fn_xhat cache (last row); hn → X_hn (bf16 head dW operand) AND reuse the
1619	        // X_hn bf16 as the scalar head input (read back below).
1620	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1621	            float xh = (hlast[j] - mean) * iv;
1622	            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
1623	            float hn = xh * w.norm_w[j] + w.norm_b[j];
1624	            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
1625	        }
1626	        __syncthreads();
1627	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16 so the
1628	        // head input == the head dW operand exactly). Store into sc.logits[si*V..].
1629	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
1630	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * dec::kD;
1631	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1632	            const float* Wr = w.out_w + (int64_t)o * dec::kD;
1633	            float acc = w.out_b[o];
1634	            #pragma unroll 4
1635	            for (int k = 0; k < dec::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
1636	            lg[o] = acc;
1637	        }
1638	        __syncthreads();
1639	        int tgt = tgt_ids[si_global(g0, si)];
1640	        float lmax = -CUDART_INF_F;
1641	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1642	        lmax = dec_block_max(lmax, red);
1643	        float es = 0.0f;
1644	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1645	        es = dec_block_sum(es, red);
1646	        float logz = lmax + __logf(es);
1647	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
1648	        __syncthreads();
1649	    }
1650	    return nll_acc;
1651	}
