1653	// Attention BACKWARD over a tile (the oracle's 3-pass form, tile-batched).
1654	// Reads qkv (bf16), attn weights, and dctx [nrows,d] fp32; writes dqkv [nrows,3d]
1655	// fp32 into `dqkv_out`. dsc is the per-CTA dscores scratch. Mirror of
1656	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped

1656	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped
1657	// over the tile's samples. scale = 1/sqrt(dh).
1658	__device__ __forceinline__ void dectc_attn_bwd_tile(
1659	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
1660	        const float* __restrict__ dctx, int nrows,
1661	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
1662	    const int nsamp = nrows / dec::kSeq;
1663	    const float scale = dec::attn_scale();
1664	    // A: dv[kj] = Σ_{qi>=kj} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t).
1665	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
1666	        const int si  = r / (dec::kSeq * dec::kHeads * dec::kDhead);
1667	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
1668	        const int kj  = rem / (dec::kHeads * dec::kDhead);
1669	        rem = rem % (dec::kHeads * dec::kDhead);
1670	        const int hh  = rem / dec::kDhead, t = rem % dec::kDhead;
1671	        const int qoff = hh * dec::kDhead;
1672	        const int rbase = si * dec::kSeq;
1673	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
1674	        float acc = 0.0f;
1675	        #pragma unroll
1676	        for (int qi = kj; qi < dec::kSeq; ++qi)
1677	            acc += aw[qi * dec::kSeq + kj] * dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t];
1678	        dqkv_out[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t] = acc;   // dv block
1679	    }
1680	    __syncthreads();
1681	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale, masked kj>qi → 0.
1682	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
1683	    for (int r = threadIdx.x; r < nsamp * dec::kHeads * dec::kSeq; r += blockDim.x) {
1684	        const int si = r / (dec::kHeads * dec::kSeq);
1685	        int rem = r % (dec::kHeads * dec::kSeq);
1686	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
1687	        const int qoff = hh * dec::kDhead;
1688	        const int rbase = si * dec::kSeq;
1689	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;
1690	        float datt[dec::kSeq];
1691	        #pragma unroll
1692	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1693	            if (kj > qi) { datt[kj] = 0.0f; continue; }
1694	            float acc = 0.0f;
1695	            #pragma unroll
1696	            for (int t = 0; t < dec::kDhead; ++t)
1697	                acc += dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t]
1698	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
1699	            datt[kj] = acc;
1700	        }
1701	        float dot = 0.0f;
1702	        #pragma unroll
1703	        for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * aw[qi * dec::kSeq + kj];
1704	        float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
1705	        #pragma unroll
1706	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1707	            float a = aw[qi * dec::kSeq + kj];
1708	            ds[kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale : 0.0f;
1709	        }
1710	    }
1711	    __syncthreads();
1712	    // C: dq[qi] = Σ_kj ds[qi,kj]*k[kj]; dk[kj] = Σ_qi ds[qi,kj]*q[qi]. Owner: (sample,pos,head,t).
1713	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
1714	        const int si = r / (dec::kSeq * dec::kHeads * dec::kDhead);
1715	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
1716	        const int pos = rem / (dec::kHeads * dec::kDhead);
1717	        rem = rem % (dec::kHeads * dec::kDhead);
1718	        const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
1719	        const int qoff = hh * dec::kDhead;
1720	        const int rbase = si * dec::kSeq;
1721	        const float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
1722	        float dq = 0.0f, dk = 0.0f;
1723	        #pragma unroll
1724	        for (int kj = 0; kj < dec::kSeq; ++kj) {
1725	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
1726	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
1727	        }
1728	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
1729	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
1730	    }
1731	    __syncthreads();
1732	}
1733	
1734	// ════════════════════════════════════════════════════════════════════════
1735	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
1736	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
1737	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
1738	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
1739	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
1740	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
1741	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
1742	//
1743	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
1744	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
1745	//  is the dedicated scratch.dh.
1746	// ════════════════════════════════════════════════════════════════════════
1747	__device__ void dectc_backward_tile(
1748	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, int B, const DecActs& acts,
1749	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
1750	        float* __restrict__ lnvec, float* __restrict__ work2,
1751	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1752	        unsigned long long* pipeBars = nullptr) {
1753	    const int nsamp = nrows / dec::kSeq;
1754	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
1755	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
1756	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
1757	    for (int li = 0; li < dec::kLayers; ++li) {
1758	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
1759	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
1760	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
1761	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
1762	    }
1763	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
1764	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
1765	
1766	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
1767	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
1768	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
1769	    // First zero scratch.dh for the whole tile (only last positions get grad).
1770	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
1771	    __syncthreads();
1772	    for (int si = 0; si < nsamp; ++si) {
1773	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
1774	        const int gs = si_global(g0, si);
1775	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
1776	        int tgt = tgt_ids[gs];
1777	        // softmax of cached logits.
1778	        float lmax = -CUDART_INF_F;
1779	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1780	        lmax = dec_block_max(lmax, red);
1781	        float es = 0.0f;
1782	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1783	        es = dec_block_sum(es, red);
1784	        float inv_es = 1.0f / es;
1785	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
1786	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1787	            float smo = __expf(lg[o] - lmax) * inv_es;
1788	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1789	            lg[o] = dl;
1790	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
1791	        }
1792	        __syncthreads();
1793	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
1794	        // Then final-norm bwd of that single row → scratch.dh[rlast].
1795	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
1796	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1797	            float dhn = 0.0f;
1798	            for (int o = 0; o < dec::kVocab; ++o)
1799	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
1800	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
1801	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
1802	        }
1803	        __syncthreads();
1804	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
1805	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1806	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
1807	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
1808	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1809	        }
1810	        __syncthreads();
1811	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
1812	        {
1813	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
1814	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
1815	            float sda = 0.0f, sdax = 0.0f;
1816	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1817	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1818	            }
1819	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
1820	            float iv = sc.fni[rlast];
1821	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1822	                float dxhat = dyr[j] * w.norm_w[j];
1823	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1824	            }
1825	            __syncthreads();
1826	        }
1827	    }
1828	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
1829	
1830	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
1831	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
1832	    //    recompute). ──
1833	    for (int li = dec::kLayers - 1; li >= 0; --li) {
1834	        const DecWeights::Layer& L = w.layer[li];
1835	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1836	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1837	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1838	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1839	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1840	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1841	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1842	        }
1843	        __syncthreads();
1844	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1845	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1846	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, wb.ff2_wT[li],
1847	                                           sc.work, dec::kDff, dec::kD, sA, sB, pipeBars);  // dgact [nrows,dff]
1848	        __syncthreads();
1849	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1850	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1851	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1852	            sc.work[idx] = dff0;
1853	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1854	        }
1855	        __syncthreads();
1856	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1857	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1858	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, wb.ff0_wT[li],
1859	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB, pipeBars);  // dx1_ffn [nrows,d]
1860	        __syncthreads();
1861	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1862	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1863	        __syncthreads();
1864	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
1865	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1866	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1867	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
1868	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
1869	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
1870	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1871	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
1872	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1873	        }
1874	        __syncthreads();
1875	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1876	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, wb.out_wT[li],
1877	                                           sc.work, dec::kD, dec::kD, sA, sB, pipeBars);  // dctx
1878	        __syncthreads();
1879	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
1880	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
1881	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1882	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
1883	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
1884	        __syncthreads();
1885	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
1886	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1887	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, wb.in_wT[li],
1888	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB, pipeBars);  // dx_in_attn
1889	        __syncthreads();
1890	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1891	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1892	        __syncthreads();
1893	    }
1894	
1895	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
1896	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
1897	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1898	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
1899	    __syncthreads();
1900	}
