1902	// ════════════════════════════════════════════════════════════════════════
1903	//  SAM-cell-scoped OUT-OF-LINE tile shims (reg-pressure campaign C2 -- the
1904	//  mamba precedent, model_stage_mamba_tc.cuh mbtc_forward_tile/backward_tile,
1905	//  SCOPED).  The SAM-coupled cells (LookSAM/SG11/SG15/SG2) run the heavy tile
1906	//  fwd+bwd TWICE per step (P1 + the P2.4 SAM 2nd pass); inlining both copies
1907	//  into one kernel blows the 255-reg budget by ~15 KB of hot-loop spills.
1908	//  Routing BOTH passes of those cells through these __noinline__ shims gives
1909	//  one shared out-of-line frame (measured: total spill bytes roughly halve and
1910	//  leave the entry body nearly clean).  The single-pass cells keep calling the
1911	//  inline bodies directly -- their allocation (255 regs, ZERO spills) is
1912	//  byte-identical to the pre-campaign engine, never taxed with an ABI boundary.
1913	//  Math identical; warpgroup-uniform call (whole CTA enters/exits together) so
1914	//  the wgmma fence/commit/wait choreography inside is well-formed.
1915	// ════════════════════════════════════════════════════════════════════════
1916	__device__ __noinline__ float dectc_forward_tile_outlined(
1917	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
1918	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
1919	        const int* __restrict__ tgt_ids,
1920	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1921	        unsigned long long* pipeBars = nullptr) {
1922	    return dectc_forward_tile(w, wb, g0, nrows, acts, sc, tok_ids, tgt_ids, sA, sB, red, pipeBars);
1923	}
1924	__device__ __noinline__ void dectc_backward_tile_outlined(
1925	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, int B, const DecActs& acts,
1926	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
1927	        float* __restrict__ lnvec, float* __restrict__ work2,
1928	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1929	        unsigned long long* pipeBars = nullptr) {
1930	    dectc_backward_tile(w, wb, g0, nrows, B, acts, sc, tgt_ids, lnvec, work2, sA, sB, red, pipeBars);
1931	}
