1933	// ════════════════════════════════════════════════════════════════════════
1934	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1935	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1936	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1937	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1938	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1939	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1940	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1941	//
1942	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1943	//  the contraction length K (T for per-position weights, B for the head).
1944	// ════════════════════════════════════════════════════════════════════════
1945	struct DecDwSpec {
1946	    const __nv_bfloat16* dY;   // [K, Nout]
1947	    const __nv_bfloat16* X;    // [K, Kin]
1948	    int Nout; int Kin; int K;
1949	    int grad_off;              // element offset of this weight in `grad`
1950	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1951	    int bias_off;              // element offset of the bias in `grad`
1952	#if SG_TUNED_DEC_DW_STAGE
1953	    // CONTIGUOUS-TRANSPOSE staging scratch (SG_TUNED_DEC_DW_STAGE=1 only). These
1954	    // three pointers exist ONLY when the macro is set, so the scalar-default
1955	    // struct (and therefore DecTcSmem's smem footprint + the kernel's register
1956	    // allocation) is BYTE-IDENTICAL to every shipped build (PTX-verified). dYt =
1957	    // K-major TRANSPOSE of dY, shape [Mpad, K] row-major (dYt[m,k] = dY[k,m]); Xt
1958	    // = [Kin, K] (Xt[n,k] = X[k,n]). Rows are K-CONTIGUOUS + 16B-aligned (K is a
1959	    // multiple of kWgmmaAtomK=16 ⇒ 8 bf16), so DecGmemTileSrcA/B read them with
1960	    // the proven 16B cp.async ring instead of the 2-byte transposed-strided
1961	    // gather. Filled ONCE per step by dectc_dw_transpose_operands (a pure bf16
1962	    // copy — no math → parity-safe).
1963	    __nv_bfloat16* dYt;        // [Mpad, K] (transposed dY) — null unless active
1964	    __nv_bfloat16* Xt;         // [Kin,  K] (transposed X)  — null unless active
1965	    int64_t t_off;             // element offset of (dYt|Xt) base in the dW-T scratch
1966	#endif
1967	};
1968	
1969	// ── CONTIGUOUS-TRANSPOSE dW scratch geometry (SG_TUNED_DEC_DW_STAGE=1). The 9
1970	//    weights' transposed operands (dYt[Nout,K] + Xt[Kin,K]) are packed into ONE
1971	//    contiguous bf16 region. Per weight s the block is (Nout_s + Kin_s)·K_s bf16:
1972	//    dYt at base+0, Xt at base+Nout_s·K_s. The SAME running-offset walk is used
1973	//    by the host workspace sizer (dec_tc_dw_transpose_floats) and the device spec
1974	//    builder (dectc_build_dw_specs) so the carve and the kernel agree exactly. K_s
1975	//    is T for the 8 layer weights, B for the head — both multiples of kWgmmaAtomK
1976	//    in every (B, kSeq) the bench/production use (so each transposed ROW is 16B-
1977	//    aligned, the cp.async-ring chunk16 requirement). Returns bf16 ELEMENTS. ──
1978	// Per-weight transpose-block bf16 elems: dYt is row-padded to a multiple of 64
1979	// (the engine's m64 atom) so the cp.async ring's UNGUARDED A-row reads (it has no
1980	// row_valid check on A) never index past the valid Nout rows — pad rows are
1981	// zeroed (inert in the wgmma). Xt is NOT row-padded (the ring guards B rows via
1982	// row_valid → only valid Kin rows are read; pad cols are zero-filled in smem).
1983	__host__ __device__ __forceinline__ int64_t dec_dw_mpad(int Nout) {
1984	    return (int64_t)((Nout + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM) * wgs::kWgmmaAtomM;
1985	}
1986	__host__ __device__ __forceinline__ int64_t dec_dw_weight_t_elems(int Nout, int Kin, int64_t K) {
1987	    return (dec_dw_mpad(Nout) + (int64_t)Kin) * K;     // dYt[Mpad,K] + Xt[Kin,K]
1988	}
1989	// True only when the contiguous-transpose path is BOTH selected (stage==1) AND
1990	// actually wired (single-CTA dW, splitk==1 — the proof path; the split-K path
1991	// keeps the lambda gather). When false the scratch is 0-sized / unused and the
1992	// run-tile never reads dYt/Xt, so the workspace + control flow are byte-identical
1993	// to the scalar default.
1994	constexpr bool kDecDwTransposeActive = (kDecDwStage == 1) && (kDecDwSplitK == 1);
1995	
1996	__host__ __device__ __forceinline__ int64_t dec_dw_transpose_elems(int B, int T) {
1997	    if (!kDecDwTransposeActive) return 0;
1998	    const int64_t Kly = T, Khd = B;
1999	    int64_t e = 0;
2000	    // 8 layer weights (per layer: qkv 3d×d, attn_out d×d, ff0 dff×d, ff2 d×dff).
2001	    for (int li = 0; li < dec::kLayers; ++li) {
2002	        e += dec_dw_weight_t_elems(3 * dec::kD, dec::kD,   Kly);  // qkv
2003	        e += dec_dw_weight_t_elems(dec::kD,     dec::kD,   Kly);  // attn_out
2004	        e += dec_dw_weight_t_elems(dec::kDff,   dec::kD,   Kly);  // ff0
2005	        e += dec_dw_weight_t_elems(dec::kD,     dec::kDff, Kly);  // ff2
2006	    }
2007	    e += dec_dw_weight_t_elems(dec::kVocab, dec::kD, Khd);        // head (K=B)
2008	    return e;
2009	}
