2076	// ── CONTIGUOUS-TRANSPOSE PASS (SG_TUNED_DEC_DW_STAGE=1). Grid-cooperatively
2077	//    transpose each weight's dY[K,Nout] → dYt[Nout,K] and X[K,Kin] → Xt[Kin,K]
2078	//    into the packed dW-T scratch the specs bind. ELEMENT-OWNED (one writer per
2079	//    output element, fixed mapping) → DETERMINISTIC and A/A/A-safe; PURE bf16
2080	//    COPY (dYt[m,k]=dY[k,m] — NO arithmetic, NO reduction) → fp64-oracle parity
2081	//    is trivially preserved (the wgmma later consumes the SAME bf16 operand
2082	//    values in the SAME ascending-k order; only their MEMORY LAYOUT changed from
2083	//    transposed-strided gmem to K-contiguous gmem). Called by ALL CTAs after the
2084	//    backward writes dY/X to acts and BEFORE the dW phase, fenced by the existing
2085	//    B1 grid barrier (no new barrier). The total work is Σ_s (Nout_s+Kin_s)·K_s
2086	//    bf16 stores, touched ONCE per step and reused across every dW work item +
2087	//    split-K chunk of that weight. ──
2088	__device__ __forceinline__ void dectc_dw_transpose_operands(
2089	        const DecDwSpec spec[9], int cta, int nCTA) {
2090	#if SG_TUNED_DEC_DW_STAGE
2091	    if constexpr (!kDecDwTransposeActive) { (void)spec; (void)cta; (void)nCTA; return; }
2092	    const int tpb = blockDim.x;
2093	    const int64_t stride = (int64_t)nCTA * tpb;
2094	    const int64_t lane0  = (int64_t)cta * tpb + threadIdx.x;
2095	    for (int s = 0; s < 9; ++s) {
2096	        const DecDwSpec& sp = spec[s];
2097	        if (sp.dYt == nullptr) continue;
2098	        const int64_t K = sp.K, Nout = sp.Nout, Kin = sp.Kin;
2099	        const int64_t Mpad = dec_dw_mpad(sp.Nout);
2100	        // dYt[m,k] = dY[k,m] for m<Nout; pad rows [Nout,Mpad) = 0 (inert — the
2101	        // ring reads A rows unguarded, so the row dim is padded to a 64-atom
2102	        // boundary). Linear out-index i = m*K+k over the FULL padded [Mpad,K).
2103	        const int64_t ndy = Mpad * K;
2104	        for (int64_t i = lane0; i < ndy; i += stride) {
2105	            const int64_t m = i / K, k = i % K;
2106	            sp.dYt[i] = (m < Nout) ? sp.dY[k * Nout + m] : __float2bfloat16(0.f);
2107	        }
2108	        // Xt[n,k] = X[k,n], n in [0,Kin), k in [0,K). Linear out-index i = n*K+k.
2109	        // (No row pad: the ring guards B rows via row_valid → pad N-tile cols are
2110	        // zero-filled in smem, never read from Xt.)
2111	        const int64_t nx = Kin * K;
2112	        for (int64_t i = lane0; i < nx; i += stride) {
2113	            const int64_t n = i / K, k = i % K;
2114	            sp.Xt[i] = sp.X[k * Kin + n];
2115	        }
2116	    }
2117	#else
2118	    (void)spec; (void)cta; (void)nCTA;   // scalar default: no transpose pass
2119	#endif
2120	}
