2230	// ════════════════════════════════════════════════════════════════════════
2231	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
2232	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
2233	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
2234	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
2235	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
2236	//  reduce sums the G partials into grad — no float atomics, fixed order, so
2237	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
2238	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
2239	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
2240	//  kc) at dw_part[((gt*G+kc)) * (kDecDwIL·64·kDecMaxTileN) + lr*kDecMaxTileN + col]
2241	//  — each work item gt is an M-atom GROUP (up to kDecDwIL=2 stacked m64 atoms, H3),
2242	//  so its slot holds kDecDwIL·64 group-local rows (lr). Decoder K varies per spec:
2243	//  layer dW K=T, head dW K=B (so kc_steps reads sp.K).
2244	// ════════════════════════════════════════════════════════════════════════
2245	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
2246	// Floats per (gt,kc) split-K slot: a work item is an M-atom GROUP of up to kDecDwIL
2247	// stacked m64 atoms → kDecDwIL·64 rows × N cols. (Was 64·N for the 1-atom item.)
2248	constexpr int kDecDwTileFloats = kDecDwIL * wgs::kWgmmaAtomM * kDecMaxTileN;
2249	
2250	// COMPILE-TIME max #dW output WORK ITEMS (the 9 dW have fixed Nout/Kin; decoder
2251	// dims are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff
2252	// ×d), ff2(d×dff), N=kDecMaxTileN; + head(V×d). The M factor is now M-atom GROUPS
2253	// of kDecDwIL (ceil(atoms/kDecDwIL)), matching dec_dw_groups — NOT single atoms.
2254	constexpr int kDecDwMGroups(int Nout) {                 // ceil(ceil(Nout/64)/kDecDwIL)
2255	    return (((Nout + 63) / 64) + kDecDwIL - 1) / kDecDwIL;
2256	}
2257	constexpr int kDecDwTilesPerLayer =
2258	      kDecDwMGroups(3*dec::kD) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
2259	    + kDecDwMGroups(dec::kD)   * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
2260	    + kDecDwMGroups(dec::kDff) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
2261	    + kDecDwMGroups(dec::kD)   * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
2262	constexpr int kDecDwHeadTiles =
2263	      kDecDwMGroups(dec::kVocab) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
2264	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
2265	
2266	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
2267	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
2268	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
2269	}
2270	
2271	// Decode global dW work-item index gt → (spec index s, m_group, n_tile). Single-
2272	// source: m_group indexes M-atom GROUPS of kDecDwIL (group's first atom = m_group·
2273	// kDecDwIL, base row = m_group·kDecDwIL·64).
2274	template <int N>
2275	__device__ __forceinline__ void dectc_dw_decode(
2276	        const DecDwSpec spec[9], int gt, int& s, int& m_group, int& n_tile) {
2277	    int acc = 0;
2278	    for (s = 0; s < 9; ++s) {
2279	        const int ng = dec_dw_groups(spec[s].Nout);
2280	        const int nt = (spec[s].Kin + N - 1) / N;
2281	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; return; }
2282	        acc += ng * nt;
2283	    }
2284	    s = 8; m_group = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
2285	}
2286	
2287	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
2288	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
2289	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
2290	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
2291	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
2292	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
2293	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
2294	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
2295	template <int N>
2296	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
2297	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
2298	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
2299	    int s, m_group, n_tile;
2300	    dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
2301	    const DecDwSpec& sp = spec[s];
2302	    const int n_atoms = dec_dw_atoms(sp.Nout);
2303	    const int a0 = m_group * kDecDwIL;                      // first atom of the group
2304	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
2305	    const int mbase = a0 * 64;
2306	    const int n0 = n_tile * N;
2307	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
2308	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
2309	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
2310	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
2311	    // Slot holds the GROUP's kDecDwIL·64 rows (lr) × N cols (kDecDwTileFloats).
2312	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
2313	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
2314	    // uninitialized accumulator → zero the WHOLE group slot + return instead of
2315	    // running it (the reduce sums all G slots unconditionally, so an empty chunk
2316	    // MUST be 0). Zero the full kDecDwIL·64·N slot (only g_atoms·64 rows are valid
2317	    // but the reduce reads only valid rows; zeroing all keeps it simple + safe).
2318	    if (kc_steps <= 0) {
2319	        for (int i = threadIdx.x; i < kDecDwTileFloats; i += blockDim.x) slot[i] = 0.0f;
2320	        __syncthreads();
2321	        return;
2322	    }
2323	    const int Nout = sp.Nout, Kin = sp.Kin;
2324	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
2325	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
2326	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
2327	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
2328	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
2329	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it; engine adds mbase0=mbase);
2330	    // the slot holds the GROUP's kDecDwIL·64 LOCAL rows → index by (m - mbase). The
2331	    // engine emits group-local rows in [0, g_atoms·64); writing them by (m-mbase)
2332	    // fills the lower g_atoms·64 rows (a ragged final group's tail rows stay as the
2333	    // zeroed/garbage upper rows but the reduce reads only valid rows → never used).
2334	    auto out  = [&] (int m, int n, float v) {
2335	        const int lr = m - mbase;
2336	        if (lr >= 0 && lr < kDecDwIL * 64 && n < N) slot[(int64_t)lr * N + n] = v; };
2337	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
2338	        mbase, g_atoms, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
2339	}
2340	
2341	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
2342	// → grad. Same (gt → geometry) decode as the partial.
2343	template <int N>
2344	__device__ __forceinline__ void dectc_dw_reduce_splitk(
2345	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
2346	        float* __restrict__ grad, int cta, int nCTA) {
2347	    for (int gt = cta; gt < n_dw; gt += nCTA) {
2348	        int s, m_group, n_tile;
2349	        dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
2350	        const DecDwSpec& sp = spec[s];
2351	        const int mbase = m_group * kDecDwIL * 64;          // group's first global row
2352	        const int n0 = n_tile * N;
2353	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
2354	        // Valid group rows: up to kDecDwIL·64, clamped to the weight's row count.
2355	        const int grp_rows = kDecDwIL * 64;
2356	        const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
2357	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
2358	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
2359	            const int row = idx / n_real, col = idx % n_real;   // row = group-local lr
2360	            float accv = 0.0f;
2361	            for (int kc = 0; kc < G; ++kc)
2362	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
2363	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
2364	        }
2365	    }
2366	}
