2411	// ════════════════════════════════════════════════════════════════════════
2412	//  P2 — EMBEDDING grad (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
2413	//
2414	//  WAS (the owner-LINEAR-SCAN, task #13 H2 target): each of V owner-CTAs scanned
2415	//  ALL T tokens (`if tok_ids[t]==r` per token), re-reading the WHOLE dh0 stream V
2416	//  times — O(V·d·T) work + V passes over 134 MB of dh0, where O(d·T) (ONE pass)
2417	//  suffices. V=99<132 left 33 CTAs idle; threads beyond d idled per owner; pos
2418	//  used only S=4 owner-CTAs scanning all T with a t%S branch.
2419	//
2420	//  NOW (H2 — counting-sort token lists + flat-element grid-stride):
2421	//    BUILD (dectc_embed_build_lists, once, cta 0, in the P1 window so it overlaps
2422	//    fwd/bwd and adds NO barrier — B1 already fences it before P2 consumes):
2423	//    a deterministic integer counting sort over tok_ids → row_start[V+1] (CSR
2424	//    offsets) + perm[T] (token positions bucketed by vocab row, ASCENDING t
2425	//    within each row, because the scatter visits t ascending and appends).
2426	//    CONSUME (dectc_embed_owner_scan): a flat grid-stride over ALL V·d output
2427	//    elements. Element (r,j) walks ONLY row r's own tokens perm[row_start[r] ..
2428	//    row_start[r+1]) in ascending-t order, reading dh0[perm[i]·d + j]. Total
2429	//    work collapses to O(d·T) (each dh0 value read once in aggregate); reads are
2430	//    COALESCED (consecutive threads = consecutive j on the same token row); ALL
2431	//    132 CTAs + full blockDim are busy (V·d=101376 elems ≫ 132·256). pos is the
2432	//    same flat grid-stride but needs NO list: tokens with (t%S)==p are exactly
2433	//    t = p, p+S, …, p+(B-1)·S (T=B·S), a closed-form ascending walk of length B.
2434	//
2435	//  DETERMINISM: per row the accumulation order over its tokens is the SAME fixed
2436	//  ascending-t order as the old scan (perm is built ascending; pos walk is
2437	//  ascending) → bitwise-identical fp32 accumulation, no float atomics, no timing-
2438	//  dependent order. The build is integer-exact (histogram counts + prefix +
2439	//  serial ascending scatter), so row_start/perm are bit-identical every rerun.
2440	//
2441	//  PORTABLE: this CSR-bucket + flat-element grid-stride is the general pattern for
2442	//  any "gather grad into a small set of embedding/lookup rows" — vit patch-proj /
2443	//  pos-embed rows and mamba's embedding will reuse dectc_embed_build_lists +
2444	//  this consume verbatim (only the row count V and the membership map differ; a
2445	//  structural map like pos needs no list at all).
2446	// ════════════════════════════════════════════════════════════════════════
2447	
2448	// Scratch float count for the embedding token lists (host carves it from the
2449	// workspace tail). row_start[V+1] + perm[T], stored as int32 (1 float slot each).
2450	__host__ __device__ __forceinline__ int64_t dec_embed_lists_floats(int T) {
2451	    return (int64_t)(dec::kVocab + 1) + (int64_t)T;
2452	}
2453	
2454	// BUILD the per-vocab-row token lists (counting sort). Single CTA (caller guards
2455	// cta==0); runs in the P1 window so it overlaps fwd/bwd and the existing B1
2456	// barrier fences it before the P2 consume — NO new barrier. `row_start` is
2457	// [V+1] int32 (CSR offsets), `perm` is [T] int32 (token positions, ascending t
2458	// within each vocab-row bucket). All integer ops → bit-exact + deterministic.
2459	//
2460	// COST: O(T), PARALLEL over kW worker lanes (HBM-latency hidden) so the build is a
2461	// few hundred µs — far below the consume saving it enables. DETERMINISM via a fixed
2462	// STRUCTURAL decomposition: worker w owns the CONTIGUOUS t-chunk [w·C,(w+1)·C); it
2463	// histograms then scatters its chunk in ascending t into a per-(worker,row) slice
2464	// of perm whose base sits AFTER all lower-w workers' slices for the same row. Lower
2465	// w ⇒ lower t, and within a worker ascending t ⇒ each row's perm bucket is GLOBALLY
2466	// ascending t — the SAME order the old single-cursor scatter (and the old owner-scan
2467	// accumulation) produced, so bit-identical. All integer ops; no atomics on the hot
2468	// path. tok_ids is HBM int32 [T]. row_start is [V+1] (CSR offsets); perm is [T].
2469	__device__ __forceinline__ void dectc_embed_build_lists(
2470	        const int* __restrict__ tok_ids, int T,
2471	        int* __restrict__ row_start, int* __restrict__ perm) {
2472	    constexpr int kW = 64;                         // worker lanes (latency hiding)
2473	    __shared__ int wcnt[kW * dec::kVocab];         // per-(worker,row) count, then base cursor
2474	    // floor-balanced contiguous t-chunk per worker w: [c0(w), c0(w+1)).
2475	    auto c0 = [&] (int w) -> int { return (int)(((int64_t)w * T) / kW); };
2476	    // 1) zero the per-worker histograms (all threads).
2477	    for (int i = threadIdx.x; i < kW * dec::kVocab; i += blockDim.x) wcnt[i] = 0;
2478	    __syncthreads();
2479	    // 2) each of the first kW threads histograms its contiguous t-chunk into its own
2480	    //    row of wcnt (no atomics — private per worker).
2481	    if (threadIdx.x < kW) {
2482	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
2483	        int* my = wcnt + (int64_t)w * dec::kVocab;
2484	        for (int t = e0; t < e1; ++t) {
2485	            const int r = tok_ids[t];
2486	            if (r >= 0 && r < dec::kVocab) my[r]++;
2487	        }
2488	    }
2489	    __syncthreads();
2490	    // 3) exclusive prefix over r → row_start[V+1] (single thread; V tiny). totals[r]
2491	    //    = Σ_w wcnt[w][r]. row_start is exclusive over rows (CSR).
2492	    if (threadIdx.x == 0) {
2493	        int acc = 0;
2494	        for (int r = 0; r < dec::kVocab; ++r) {
2495	            row_start[r] = acc;
2496	            for (int w = 0; w < kW; ++w) acc += wcnt[(int64_t)w * dec::kVocab + r];
2497	        }
2498	        row_start[dec::kVocab] = acc;   // == #tokens with a valid row (≤ T)
2499	    }
2500	    __syncthreads();
2501	    // 4) per-(worker,row) base cursor: wcnt[w][r] ← row_start[r] + Σ_{w'<w} cnt[w'][r]
2502	    //    (ascending-worker prefix WITHIN a row → lower-t chunks land first). One
2503	    //    thread per row (V≤256 → fits blockDim) scans workers ascending.
2504	    if (threadIdx.x < dec::kVocab) {
2505	        const int r = threadIdx.x;
2506	        int base = row_start[r];
2507	        for (int w = 0; w < kW; ++w) {
2508	            int* slot = &wcnt[(int64_t)w * dec::kVocab + r];
2509	            const int c = *slot;
2510	            *slot = base;        // becomes the live append cursor for (w,r)
2511	            base += c;
2512	        }
2513	    }
2514	    __syncthreads();
2515	    // 5) scatter: each worker walks its chunk ascending t, appending t to perm at
2516	    //    its per-row cursor. Ascending t within the chunk + ascending-worker bases
2517	    //    ⇒ globally ascending t per row bucket.
2518	    if (threadIdx.x < kW) {
2519	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
2520	        int* cur = wcnt + (int64_t)w * dec::kVocab;
2521	        for (int t = e0; t < e1; ++t) {
2522	            const int r = tok_ids[t];
2523	            if (r >= 0 && r < dec::kVocab) perm[cur[r]++] = t;
2524	        }
2525	    }
2526	    __syncthreads();
2527	}
2528	
2529	// CONSUME: assemble tok + pos embedding grads from the prebuilt lists. Flat grid-
2530	// stride over V·d (tok) and S·d (pos) output elements → all CTAs + threads busy,
2531	// coalesced dh0 reads, fixed ascending-t accumulation per row (deterministic).
2532	__device__ __forceinline__ void dectc_embed_owner_scan(
2533	        const DecActs& acts, const int* __restrict__ row_start,
2534	        const int* __restrict__ perm, int T,
2535	        float* __restrict__ grad, int cta, int nCTA) {
2536	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
2537	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
2538	    const __nv_bfloat16* __restrict__ dh0 = acts.dh0;
2539	    const int stride = nCTA * blockDim.x;
2540	    const int base   = cta * blockDim.x + threadIdx.x;
2541	    // ── tok grad: element (r,j) over V·d, grid-strided. Walk ONLY row r's tokens
2542	    //    (perm[row_start[r] .. row_start[r+1])) ascending → coalesced dh0 column
2543	    //    read across the warp (consecutive j on one token row). ──
2544	    const int64_t Vd = (int64_t)dec::kVocab * dec::kD;
2545	    for (int64_t e = base; e < Vd; e += stride) {
2546	        const int r = (int)(e / dec::kD);
2547	        const int j = (int)(e - (int64_t)r * dec::kD);
2548	        const int s0 = row_start[r], s1 = row_start[r + 1];
2549	        float accv = 0.0f;
2550	        for (int i = s0; i < s1; ++i)
2551	            accv += __bfloat162float(dh0[(int64_t)perm[i] * dec::kD + j]);
2552	        grad[tok_off + e] = accv;
2553	    }
2554	    // ── pos grad: element (p,j) over S·d, grid-strided. Tokens with (t%S)==p are
2555	    //    t = p, p+S, …, p+(B-1)·S (T=B·S) — closed-form ascending walk, no list. ──
2556	    const int64_t Sd = (int64_t)dec::kSeq * dec::kD;
2557	    const int B = T / dec::kSeq;
2558	    for (int64_t e = base; e < Sd; e += stride) {
2559	        const int p = (int)(e / dec::kD);
2560	        const int j = (int)(e - (int64_t)p * dec::kD);
2561	        float accv = 0.0f;
2562	        int t = p;
2563	        for (int i = 0; i < B; ++i, t += dec::kSeq)
2564	            accv += __bfloat162float(dh0[(int64_t)t * dec::kD + j]);
2565	        grad[pos_off + e] = accv;
2566	    }
2567	}
